insert into public.site_content_blocks(key,title,content,source_reference,status,published_at) values
('manifesto.odqs','Objetivos de Desenvolvimento Quântico','[{"id":1,"title":"Programa nacional integrado","desc":"Criar um programa nacional de tecnologias quânticas que articule ciência, inovação, educação e indústria de forma coordenada e permanente."},{"id":2,"title":"Horizonte quântico 2045","desc":"Definir e cumprir metas nacionais de curto, médio e longo prazo em tecnologias quânticas, com revisões periódicas e alinhamento global."},{"id":3,"title":"Ciência como estratégia de estado","desc":"Fortalecer a ciência como pilar do desenvolvimento sustentável, integrando tecnologias quânticas às agendas nacionais de soberania, economia e inclusão."},{"id":4,"title":"Investimento sustentado e protegido","desc":"Garantir financiamento estável, crescente e protegido para CT&I em tecnologias quânticas, com fundos públicos e parcerias privadas."},{"id":5,"title":"Infraestrutura nacional de excelência","desc":"Consolidar uma rede nacional de laboratórios e centros de competência em tecnologias quânticas, com acesso amplo e atualizado."},{"id":6,"title":"Formação e talento quântico","desc":"Formar, atrair e reter profissionais altamente qualificados em ciência, engenharia, computação e inovação quântica, valorizando a carreira científica."},{"id":7,"title":"Inovação e empreendedorismo quântico","desc":"Apoiar startups e empresas deep tech por meio de fundos, incubadoras e programas de aceleração para transformar ciência em soluções de mercado."},{"id":8,"title":"Cooperação e governança quântica","desc":"Criar estruturas de governança e articulação nacional e internacional, posicionando o Brasil como ator estratégico no cenário global quântico."},{"id":9,"title":"Indústria quântica brasileira","desc":"Estimular a produção e aplicação industrial de tecnologias quânticas, fomentando a nacionalização de componentes e a geração de novos mercados."},{"id":10,"title":"Cultura científica e inclusão quântica","desc":"Popularizar o conhecimento quântico com ações de comunicação, educação básica e inclusão, promovendo o engajamento da sociedade com a ciência."},{"id":11,"title":"Soberania e segurança quântica","desc":"Desenvolver soluções quânticas nacionais para segurança cibernética, comunicações e defesa, garantindo a proteção estratégica e tecnológica do país."}]','src_semAssets.zip/pages/Manifesto.tsx — transcrição literal','published',now()),
('manifesto.cartas','Cartas Macrorregionais','[{"region":"Carta do Sudeste","text":"A Carta de Sorocaba marcou o início da Jornada Nacional do Manifesto Quântico no Sudeste, estabelecendo diretrizes técnicas, institucionais e estratégicas. As atividades abriram frentes em algoritmos, semicondutores, sensores e segurança pós-quântica, com forte potencial de PD&I junto a ambientes industriais e acadêmicos, incluindo a construção do centro tecnológico nacional de Iperó, na região metropolitana. A agenda incluiu participação em eventos e instâncias institucionais, como MVP Conf, Festival MOBI e Audiência Pública na ALESP, além do lançamento da LACQ USP, fortalecendo a formação de talentos e a base científica do Manifesto."},{"region":"Carta do Norte","text":"A etapa amazônica integrou o Manifesto à Região Norte, aprofundando agendas com biotecnologia, semicondutores, inovação industrial e governo. Houve avanços em sensoriamento quântico, segurança digital e aplicações industriais, com participação no IV ENAEPE, em Manaus. A Carta da Amazônia consolidou-se como documento estruturante, e a criação da LACQ UEA ampliou a rede nacional de conexão acadêmica quântica. As articulações do Foton fortaleceram a presença institucional e abriram novas frentes de PD&I."},{"region":"Carta do Nordeste","text":"No Nordeste, a Jornada conectou polos de inovação, fotônica, computação e transformação digital de Recife e João Pessoa, com forte engajamento de universidades, ambientes de tecnologia e articulações com o poder público. As atividades mapearam desafios e oportunidades em PD&I e fortaleceram a colaboração científica regional, com apoio das Ligas Acadêmicas da UFPE e UFPB. As contribuições ampliaram a base do Manifesto e consolidaram o alinhamento institucional na região."},{"region":"Carta do Centro-oeste","text":"No Centro-Oeste, a Jornada avançou com reuniões estratégicas em Brasília, no MCTI e na Softex Nacional, fortalecendo o alinhamento do Manifesto com políticas públicas e programas de fomento. As discussões abordaram tecnologias habilitadoras, incentivos digitais e oportunidades de PD&I, além da estruturação de grupos de trabalho. As próximas agendas irão aprofundar a integração regional e a atuação conjunta entre academia, governo e setor produtivo, reforçando a maturidade nacional do movimento."},{"region":"Carta do Sul","text":"No Sul, o movimento avança com ações permanentes de divulgação científica e liderança técnica em tecnologia quântica. A agenda inclui visitas a ambientes de inovação e a atuação em eventos estratégicos, como Latinoware, DS Summit, Sucesu RS, Tecnopuc e Assespro RS. A formação das LACQs UTFPR-PR e PUC-RS fortaleceu a conexão entre talentos e ampliou a base acadêmica, enquanto a mobilização dos associados consolida o papel estratégico da região na construção do Manifesto."}]','src_semAssets.zip/pages/Manifesto.tsx — relatos preservados; não confirma agendas atuais','published',now()),
('manifesto.methodology','Metodologia','[{"num":1,"title":"Mobilização regional","desc":"Engajamento de lideranças das quatro hélices da inovação."},{"num":2,"title":"Consulta participativa","desc":"Coleta de percepções e propostas alinhadas aos ODQs."},{"num":3,"title":"Sistematização das contribuições","desc":"Consolidação das demandas e oportunidades regionais."},{"num":4,"title":"Articulação institucional","desc":"Conexão de universidades, empresas e governos locais."},{"num":5,"title":"Mobilização regional","desc":"Assinatura simbólica das Cartas e compartilhamento dos resultados."}]','src_semAssets.zip/pages/Manifesto.tsx — repetição de título preservada','published',now()),
('institute.values','Valores','Excelência
insert into public.site_research_lines(slug,title,summary,description,status,display_order,source_reference) values
('computacao-quantica','Computação quântica','Novas formas de processar informação. Novas perguntas para a ciência.','A computação quântica investiga como propriedades de sistemas quânticos podem ser usadas no processamento de informação. Hardware, software e firmware se encontram em uma área que exige pesquisa fundamental e colaboração entre especialidades.','published',1,'Prompt Mestre V0 §6 — descrições educativas adaptadas; não representam capacidades ou projetos ativos'),
('comunicacao-e-criptografia','Comunicação e criptografia','Conhecimento para pensar o futuro da comunicação e da segurança.','Comunicação quântica e criptografia pós-quântica são abordagens distintas. A primeira utiliza propriedades físicas de sistemas quânticos; a segunda desenvolve algoritmos criptográficos clássicos concebidos para resistir a ataques de computadores quânticos.','published',2,'Prompt Mestre V0 §6 — descrições educativas adaptadas; não representam capacidades ou projetos ativos'),
('sensores-e-materiais','Sensores e materiais quânticos','Observar com precisão para descobrir possibilidades.','Sensoriamento quântico explora propriedades quânticas para realizar medições. A pesquisa em materiais busca compreender e desenvolver propriedades físicas. Essas frentes aproximam ciência fundamental e questões de aplicação, por meio de instituições e laboratórios parceiros.','published',3,'Prompt Mestre V0 §6 — descrições educativas adaptadas; não representam capacidades ou projetos ativos'),
('algoritmos-e-otimizacao','Algoritmos e otimização','Investigar caminhos para problemas complexos.','Algoritmos quânticos e métodos híbridos são estudados para problemas de cálculo e otimização. Saúde é uma área de interesse para investigação, sem que isso represente comprovação de resultados clínicos ou garantia de vantagem computacional.','published',4,'Prompt Mestre V0 §6 — descrições educativas adaptadas; não representam capacidades ou projetos ativos'),
('quantica-nos-negocios','Quântica nos negócios','Uma ponte entre pesquisa, organizações e sociedade.','Compreender tecnologias emergentes também envolve formação, gestão e diálogo. Essa frente aproxima o conhecimento científico das questões enfrentadas por organizações, respeitando o estágio de maturidade de cada tecnologia.','published',5,'Prompt Mestre V0 §6 — descrições educativas adaptadas; não representam capacidades ou projetos ativos')
insert into public.site_support_modalities(slug,title,summary,description,purpose,transparency_text,operational_status,public_status,display_order) values
('educacao','Abra caminhos para aprender','Apoio a materiais didáticos e atividades de aproximação com a ciência.','Possíveis destinações: materiais de ensino, impressão e recursos para atividades educacionais. Custos e ações serão definidos em orçamento aprovado. Critérios, orçamento, responsáveis pela execução e política de apoio ainda dependem de aprovação institucional.','Materiais de oficinas, recursos didáticos e divulgação científica podem ajudar a transformar curiosidade em aprendizado.','A proposta prevê divulgação das atividades realizadas e sínteses de utilização dos recursos, preservando dados pessoais dos participantes.','informational','published',1),
('computacao','Dê espaço a novas perguntas','Condições para estudar, testar hipóteses e desenvolver pesquisa.','Computação, armazenamento e ambientes de testes, conforme a necessidade de cada projeto e contratos aprovados. O apoio não dá direito de acesso a hardware quântico. Projetos elegíveis, custos e acesso a serviços ainda serão definidos. Não há reserva de capacidade computacional disponível nesta página.','Pesquisa exige ferramentas para calcular, armazenar e analisar informações.','Marcos de pesquisa e sínteses de destinação dos recursos poderão ser publicados após revisão institucional.','informational','published',2),
('eventos','Ajude a ciência a circular','Compartilhar conhecimento também faz parte da pesquisa.','Inscrições, materiais de apresentação, deslocamento e hospedagem, quando previstos e formalmente autorizados. Não existe chamada de apoio ou reembolso aberta. Elegibilidade, orçamento e seleção dependem de regulamento.','A participação em encontros pode criar conexões e colocar resultados em diálogo com a comunidade científica.','Participação, resultados compartilháveis e resumo das despesas aprovadas poderão compor os relatórios públicos.','informational','published',3),
('pesquisa','Aproxime uma ideia do mundo','Fomento a projetos com objetivos, orçamento e acompanhamento.','No modelo proposto, cada projeto terá orçamento, etapas e instituição responsável identificados antes de qualquer captação. Modelo demonstrativo, sem campanha aberta. Nenhum projeto ou meta financeira está sendo apresentado como ativo.','Conectar apoio da sociedade a uma pergunta de pesquisa com escopo definido.','Acompanhamento por marcos, atualizações autorizadas e prestação de contas após a execução.','informational','published',4),
('pesquisador','Incentive quem faz perguntas','Uma proposta de apoio com critérios e acompanhamento institucional.','A proposta considera indicação assistida de pesquisadores autorizados ou alocação institucional com critérios aprovados. Não é uma transferência direta automática a uma pessoa. Beneficiários, valores, duração e regras ainda dependem de definição. Não há bolsa, seleção ou cadastro aberto.','Criar condições para que trajetórias científicas continuem, em diferentes momentos da vida.','Critérios de seleção, destinação e relatos autorizados poderão ser disponibilizados sem expor dados particulares.','informational','published',5),
('recorrente','Faça parte da continuidade','Uma relação de longo prazo com a ciência brasileira.','A proposta é destinar apoios periódicos a programas aprovados, com regras públicas de alocação. Recorrência e faixas de reconhecimento ainda não estão ativas. Não há cobrança, assinatura ou benefício contratado.','Continuidade ajuda a planejar atividades e acompanhar sua evolução.','O modelo prevê relatórios trimestrais e reconhecimento de apoiadores somente mediante autorização expressa.','informational','published',6),
('patrocinio','Conecte sua organização à ciência','Parcerias orientadas por propósito e independência científica.','Apoio a projetos específicos, sujeito a análise de aderência, contrato e orçamento aprovado. Elegibilidade, contrapartidas, vigência e regras de conflito de interesse exigem aprovação. Não se promete retorno financeiro ou acesso a dados confidenciais.','Aproximar organizações de iniciativas de pesquisa com objetivos compartilhados e responsabilidades claras.','Relatórios e reconhecimento institucional poderão integrar acordos. Marca em materiais e encontros são possibilidades negociadas, nunca contrapartidas automáticas.','informational','published',7)
